const titles={basis:'Fakturagrundlag',shipment:'Forsendelsesbekræftelse',receipt:'Kvittering'};
const el=(tag,text)=>{const node=document.createElement(tag);if(text)node.textContent=text;return node;};
const kr=n=>n===null?'Mangler':(n/100).toLocaleString('da-DK',{minimumFractionDigits:2,maximumFractionDigits:2})+' kr.';
export function documentPanel(order,api){
 const box=el('section'),toolbar=el('div'),editor=el('div'),status=el('p');box.className='order-documents';toolbar.className='resend-tools';status.setAttribute('role','status');
 box.append(el('h3','Dokumenter til bogholder og kunde'),el('p','Fakturagrundlag til manuel oprettelse i e-conomic. Gennemse oplysningerne og hent PDF. Dokumenterne ændrer ikke ordren og sender ingen mail.'),toolbar,status,editor);
 const url=`/api/pf-orders/${order.id}/documents`;const history=el('details');history.append(el('summary','Tidligere genererede PDF’er'));box.append(history);function addHistory(record){const a=el('a',record.title+' · '+new Date(record.createdAt).toLocaleString('da-DK',{timeZone:'Europe/Copenhagen'}));a.href=url+'/'+record.id;a.target='_blank';a.rel='noopener';history.append(a,el('br'));}
 api(url).then(r=>r.json()).then(data=>{for(const record of data.documents||[])addHistory(record);for(const option of data.options){const wrap=el('div'),button=el('button',titles[option.type]);button.type='button';button.disabled=!!option.reason;button.onclick=()=>open(option.type);wrap.append(button);if(option.reason)wrap.append(el('small',option.reason));toolbar.append(wrap);}}).catch(e=>status.textContent=e.message);
 async function open(type){status.textContent='Henter ordreoplysninger…';editor.replaceChildren();try{const d=await(await api(url+'?type='+type)).json();status.textContent='';const form=el('form'),fields=el('div'),preview=el('div');fields.className='document-fields';form.append(fields);editor.append(form,preview);fields.append(el('h3',titles[type]+' · gennemse og ret'),el('p','Ordrereference: '+d.reference));
 const inputs=[];let generatedLink;
 function field(parent,label,obj,key,{multiline=false,money=false,number=false,readonly=false}={}){const wrap=el('label'),caption=el('span',label),input=el(multiline?'textarea':'input');input.value=money?(obj[key]===null?'':(obj[key]/100).toFixed(2)):obj[key]??'';if(!multiline)input.type=number||money?'number':'text';if(number||money){input.step=money?'0.01':'1';input.min='0';}input.readOnly=readonly;input.oninput=()=>{obj[key]=money?(input.value===''?null:Math.round(Number(input.value)*100)):number?(input.value===''?null:Number(input.value)):input.value;preview.replaceChildren();if(generatedLink)generatedLink.remove();};wrap.append(caption,input);parent.append(wrap);inputs.push(input);return input;}
 field(fields,'Ordredato (ÅÅÅÅ-MM-DD)',d,'date');
 const sender=el('details');sender.append(el('summary','Afsender og virksomhedsindstillinger'));fields.append(sender);sender.append(el('p','Smerch står som afsender. Gem kun fælles oplysninger som standard.'));
 for(const [key,label] of Object.entries({legalName:'Juridisk virksomhed',address:'Adresse',cvr:'CVR',email:'E-mail',phone:'Telefon'}))field(sender,label,d.company,key,{multiline:key==='address'});
 field(sender,'Standardbetalingsbetingelser (ingen kreditfrist antages)',d.company,'paymentTerms',{multiline:true});field(sender,'Standardbemærkning til bogholderen',d.company,'accountantNotes',{multiline:true});
 const save=el('button','Gem som virksomhedsindstillinger');save.type='button';save.onclick=async()=>{save.disabled=true;try{await api(url,'POST',{action:'settings',company:d.company});status.textContent='Virksomhedsindstillingerne er gemt til kommende dokumenter.';}catch(e){status.textContent=e.message;}finally{save.disabled=false;}};sender.append(save);
 fields.append(el('h4','Kunde'));
 for(const [key,label] of Object.entries({name:'Navn / firma',contact:'Kontaktperson',address:'Faktureringsadresse',email:'E-mail',cvr:'CVR (valgfrit)',ean:'EAN (valgfrit)',reference:'Kundereference (valgfrit)'})){if(type==='shipment'&&key==='address')continue;field(fields,label,d.customer,key,{multiline:key==='address'});}
 if(type!=='shipment'){const copy=el('button','Brug leveringsadresse som faktureringsadresse');copy.type='button';copy.onclick=()=>{d.customer.address=d.deliveryAddress;const input=inputs.find(i=>i.parentElement.firstChild.textContent==='Faktureringsadresse');input.value=d.deliveryAddress;preview.replaceChildren();};fields.append(copy);}
 if(type==='shipment'){field(fields,'Leveringsadresse',d,'deliveryAddress',{multiline:true});field(fields,'Afsendelsesdato (ÅÅÅÅ-MM-DD)',d,'shipDate');field(fields,'Transportør (valgfrit)',d,'carrier');field(fields,'Trackingnummer og link (valgfrit)',d,'tracking',{multiline:true});fields.append(el('p','Kontrollér afsendte antal. Ved delvis afsendelse skal antal angives; brug 0 for varer, der ikke er med.'));}
 fields.append(el('h4',type==='shipment'?'Afsendte produkter':'Varelinjer · beløb i DKK'));
 for(const [i,line] of d.lines.entries()){const row=el('fieldset');row.append(el('legend','Vare '+(i+1)));fields.append(row);field(row,'Produktbeskrivelse',line,'description',{multiline:true});field(row,'Variant / varenummer / tryk',line,'variant',{multiline:true});field(row,type==='shipment'?'Afsendt antal (maks. '+line.maxQuantity+')':'Antal',line,'quantity',{number:true,readonly:type==='receipt'});if(type!=='shipment'){field(row,'Linjetotal ekskl. moms, inkl. tryk og opstart',line,'net',{money:true,readonly:type==='receipt'});field(row,'Rabat, allerede indregnet (valgfrit)',line,'discount');}}
 if(type!=='shipment'){field(fields,'Fragt ekskl. moms',d,'freight',{money:true,readonly:type==='receipt'});field(fields,'Moms i alt',d,'vat',{money:true,readonly:type==='receipt'});fields.append(el('p','Moms hentes fra ordren. Ved rettede beløb skal moms også kontrolleres.'));field(fields,'Betalingsbetingelser',d,'paymentTerms',{multiline:true});fields.append(el('p',d.paymentStatus+(type==='receipt'?' · '+new Date(d.paidAt).toLocaleString('da-DK'):'')));}
 field(fields,type==='basis'?'Bemærkninger til bogholderen':'Bemærkninger til kunden',d,'notes',{multiline:true});
 const review=el('button','Gennemse dokument');review.type='submit';form.append(review);form.onsubmit=async event=>{event.preventDefault();review.disabled=true;preview.replaceChildren();status.textContent='Kontrollerer oplysninger…';try{const checked=await(await api(url,'POST',{action:'review',document:d})).json();status.textContent='';preview.append(el('h4','Kontrol før PDF'));if(checked.missing.length){preview.append(el('p','Følgende oplysninger mangler eller er ugyldige:'));const list=el('ul');checked.missing.forEach(m=>list.append(el('li',m)));preview.append(list);return;}
 preview.append(el('p','Afsender: Smerch · '+checked.company.legalName),el('p','Kunde: '+checked.customer.name+' · '+(type==='shipment'?checked.deliveryAddress:checked.customer.address)));
 for(const line of checked.lines)preview.append(el('p',`${line.quantity} × ${line.description}${type==='shipment'?'':' · '+kr(line.net)+' ekskl. moms'}`));
 if(type!=='shipment')preview.append(el('strong','I alt inkl. moms: '+kr(checked.total)));
 if(checked.adjusted)preview.append(el('p','Beløb eller antal afviger fra ordren. Din bemærkning medtages til bogholderen.'));
 const generate=el('button','Generér '+titles[type]+' som PDF');generate.type='button';preview.append(generate);generate.onclick=async()=>{generate.disabled=true;try{const record=await(await api(url,'POST',{action:'generate',document:d})).json();generatedLink=el('a','Åbn / hent '+record.title+' (PDF)');generatedLink.href=url+'/'+record.id;generatedLink.target='_blank';generatedLink.rel='noopener';preview.append(generatedLink);addHistory(record);status.textContent='PDF’en er gemt. Brug linket til at gennemse og hente den. Ingen mail er sendt.';}catch(e){status.textContent=e.message;generate.disabled=false;}};
 }catch(e){status.textContent=e.message;}finally{review.disabled=false;preview.scrollIntoView({block:'nearest',behavior:'smooth'});}};
 }catch(e){status.textContent=e.message;}}
 return box;
}
